 result={'id':job['task_id'],'final':(state.final_output or None) if state else None,'termination':termination or ('submitted' if state and state.status==RunStatus.COMPLETED else 'budget'),'acceptance':'not_evaluated' if not errors else 'unreviewable','assistance':'rwkv_independent','error':error,'status':state.status.value if state else 'not_started','trace_complete':not errors,'trace_errors':errors,'tool_scope':'production_full','generation_started':sum(e['type']=='model_session_generation_started' for e in records),'protocol_rejections':state.protocol_rejections if state else 0,'actions':[a.to_dict() for a in state.actions.values()] if state else [],'elapsed_seconds':time.monotonic()-started}
 save(output/'RESULT.json',result)
